wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(64110078534387406321)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'twilio sms'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P8_PLANTILLA is not null then',
'    twilio_envios.enviar_mensajes(',
'      p_id_plantilla     => :P8_PLANTILLA,',
'      p_numero_remitente => :P0_TWILIO_NUMBER',
'    );',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Mensajes Enviados'
,p_required_patch=>wwv_flow_imp.id(64108731903177339280)
,p_internal_uid=>64110078534387406321
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(64110079926728406335)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'vox sms'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  v_contenido     clob;',
'  v_mensaje       clob;',
'  v_status        varchar2(4000);',
'  v_respuesta     clob;',
'begin',
'  -- Obtener el cuerpo de la plantilla seleccionada',
'  select cuerpo_mensaje',
'    into v_contenido',
'    from plantilla_mensajes',
'   where id_plantilla = :P8_PLANTILLA;',
'',
'  -- Recorrer clientes activos',
'  for c in (',
'    select id_cliente, telefono',
'    from clientes',
'    where activo = ''S''',
'  ) loop',
'    begin',
unistr('      -- Reemplazar par\00E1metros din\00E1micos con datos del cliente'),
'      v_mensaje := reemplazar_parametros(v_contenido, c.id_cliente);',
'',
'      -- Enviar SMS usando la API de VOX',
'      vox_enviar_sms(',
'        p_nro_origen   => :P0_PHONE_NUMBER,',
'        p_nro_destino  => c.telefono,',
'        p_contenido    => dbms_lob.substr(v_mensaje, 160), -- Truncar si es muy largo',
'        p_status       => v_status,',
'        p_respuesta    => v_respuesta',
'      );',
'',
unistr('      -- Registrar el env\00EDo exitoso'),
'      insert into envio_mensajes (',
'        id_cliente,',
'        id_plantilla,',
'        mensaje_enviado,',
'        estado_envio,',
'        respuesta_api',
'      ) values (',
'        c.id_cliente,',
'        :P8_PLANTILLA,',
'        v_mensaje,',
'        v_status,',
'        v_respuesta',
'      );',
'',
'    exception',
'      when others then',
'        insert into envio_mensajes (',
'          id_cliente,',
'          id_plantilla,',
'          mensaje_enviado,',
'          estado_envio,',
'          respuesta_api',
'        ) values (',
'          c.id_cliente,',
'          :P8_PLANTILLA,',
'          v_mensaje,',
'          v_status,',
'          v_respuesta',
'        );',
'    end;',
'  end loop;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>64110079926728406335
);
end;
